def numerical_letter_grade(grades):
    """Converts a list of GPAs into their corresponding letter grades."""

    def get_gpa_to_letter(gpa):
        # Handle the highest possible case first (4.0)
        if gpa == 4.0:
            return 'A+'

        # Check ranges in descending order to ensure correct logic flow
        elif gpa > 3.7 and gpa <= 4.0:
            return 'A'
        elif gpa > 3.3 and gpa <= 3.7:
            return 'A-'
        elif gpa > 3.0 and gpa <= 3.3:
            return 'B+'
        elif gpa > 2.7 and gpa <= 3.0:
            return 'B'
        elif gpa > 2.3 and gpa <= 2.7:
            return 'B-'
        elif gpa > 2.0 and gpa <= 2.3:
            return 'C+'
        elif gpa > 1.7 and gpa <= 2.0:
            return 'C'
        elif gpa > 1.3 and gpa <= 1.7:
            return 'C-'
        elif gpa > 1.0 and gpa <= 1.3:
            return 'D+'
        elif gpa > 0.7 and gpa <= 1.0:
            return 'D'
        elif gpa > 0.0 and gpa <= 0.7:
            return 'D-'
        else: # GPA == 0.0 or effectively below the lowest threshold defined
            return 'E'

    result = []

    for grade in grades:
        letter_grade = get_gpa_to_letter(grade)
        result.append(letter_grade)

    return result

